begin;

-- flavio-bolsonaro
insert into quotes (person_id, text, language, said_on, context, source_type, source_url, source_timestamp, difficulty, kind, status, review_note)
select id, 'Fiz duas filhas exatamente para isso, quando ficar velhinho é que vai cuidar de mim, mulheres são assim, são coração', 'pt', '2026-08-05', 'No evento em que anunciou o deputado Alfredo Gaspar como vice, depois de dizer que queria uma mulher na chapa. Foi chamado de machista, comparado à "fraquejada" do pai, e aliados temeram o estrago com o eleitorado feminino.', 'discurso', 'https://www.cnnbrasil.com.br/politica/flavio-diz-que-teve-duas-filhas-para-que-elas-cuidem-dele-na-velhice/', null, 1, 'polemica', 'draft', 'Fonte: CNN Brasil · Por que: Filhas feitas "para cuidar dele na velhice" · Obs.: Repercussão em https://www.metropoles.com/blog-do-noblat/o-bastidor-da-frase-de-flavio-que-revive-a-fraquejada-do-pai'
from people where slug = 'flavio-bolsonaro'
  and not exists (select 1 from quotes where text = 'Fiz duas filhas exatamente para isso, quando ficar velhinho é que vai cuidar de mim, mulheres são assim, são coração');
insert into quotes (person_id, text, language, said_on, context, source_type, source_url, source_timestamp, difficulty, kind, status, review_note)
select id, 'Que inveja. Você não gostaria de passar alguns meses aqui nos ajudando a combater essas organizações terroristas?', 'pt', '2025-10-23', 'Resposta a um post do secretário de Guerra dos EUA, Pete Hegseth, sobre o bombardeio de um barco de supostos traficantes no Pacífico. Disse que havia barcos assim na Baía de Guanabara. Foi acusado de pedir ataque estrangeiro ao Rio, e o PT o denunciou ao STF.', 'post', 'https://www.terra.com.br/noticias/brasil/politica/flavio-bolsonaro-sugere-que-eua-ataquem-barcos-com-drogas-na-baia-de-guanabara-que-inveja,85dbc8e703ac55d32ae8e32dc884f4afxie2ro8s.html', null, 2, 'polemica', 'draft', 'Fonte: Terra · Por que: Senador com "inveja" de bombardeio americano · Obs.: O post original é em inglês; o texto é a tradução do Terra. Denúncia ao STF em https://www.metropoles.com/brasil/pt-denuncia-flavio-bolsonaro-ao-stf-apos-pedido-de-ajuda-aos-eua'
from people where slug = 'flavio-bolsonaro'
  and not exists (select 1 from quotes where text = 'Que inveja. Você não gostaria de passar alguns meses aqui nos ajudando a combater essas organizações terroristas?');

-- lula
insert into quotes (person_id, text, language, said_on, context, source_type, source_url, source_timestamp, difficulty, kind, status, review_note)
select id, 'O que está acontecendo na Faixa de Gaza com o povo palestino não existiu em nenhum outro momento histórico. Aliás, existiu. Quando Hitler resolveu matar os judeus', 'pt', '2024-02-18', 'Em entrevista na Etiópia, comparando a guerra em Gaza ao Holocausto. Israel declarou Lula "persona non grata", o Brasil chamou de volta o embaixador, a oposição protocolou pedido de impeachment e 83% dos brasileiros discordaram da fala.', 'entrevista', 'https://www.cnnbrasil.com.br/politica/entenda-o-que-lula-falou-sobre-holocausto-e-israel/', null, 1, 'polemica', 'draft', 'Fonte: CNN Brasil · Por que: Comparou Israel ao Holocausto e virou persona non grata'
