insert into quotes (person_id, text, language, said_on, context, source_type, source_url, source_timestamp, difficulty, kind, status, review_note)
select id, 'Ainda bem que a natureza, que a natureza, contra a vontade da humanidade, criou esse monstro chamado coronavírus', 'pt', '2020-05-19', 'Em entrevista à Carta Capital, no começo da pandemia, dizendo que o vírus mostrava que só o Estado resolve certas crises. A frase foi duramente criticada num momento em que o Brasil já somava milhares de mortos.', 'entrevista', 'https://www.correiobraziliense.com.br/app/noticia/politica/2020/05/20/interna_politica,856754/lula-ainda-bem-que-a-natureza-criou-esse-monstro-chamado-coronavirus.shtml', null, 2, 'polemica', 'draft', 'Fonte: Correio Braziliense · Por que: "Ainda bem" que veio o coronavírus'
