insert into quotes (person_id, text, language, said_on, context, source_type, source_url, source_timestamp, difficulty, kind, status, review_note)
select id, 'A Venezuela tem mais eleições do que o Brasil. O conceito de democracia é relativo para você e para mim', 'pt', null, 'Em entrevista à Rádio Gaúcha, perguntado por que o governo não chamava o regime de Maduro de antidemocrático. Semanas antes, Boric e Lacalle Pou já tinham criticado Lula por defender Maduro; a frase virou bordão da oposição.', 'entrevista', 'https://www.correiobraziliense.com.br/politica/2023/06/5105586-lula-sobre-venezuela-conceito-de-democracia-e-relativo-para-voce-e-para-mim.html', null, 1, 'polemica', 'draft', 'Fonte: Correio Braziliense · Por que: Democracia "relativa" para defender Maduro · Obs.: Sem data exata; junho de 2023.'
from people where slug = 'lula'
  and not exists (select 1 from quotes where text = 'A Venezuela tem mais eleições do que o Brasil. O conceito de democracia é relativo para você e para mim');
insert into quotes (person_id, text, language, said_on, context, source_type, source_url, source_timestamp, difficulty, kind, status, review_note)
select id, 'É uma crise causada e fomentada por comportamentos irracionais de gente branca de olhos azuis', 'pt', '2009-03-26', 'Em entrevista coletiva ao lado do primeiro-ministro britânico Gordon Brown, sobre a crise financeira de 2008. A frase rodou o mundo e o Planalto teve de dizer que era só uma "metáfora", sem conotação racista.', 'entrevista', 'https://www.terra.com.br/economia/crise-foi-provocada-por-brancos-de-olhos-azuis-diz-lula,308f17a7adc4b310VgnCLD200000bbcceb0aRCRD.html', null, 1, 'polemica', 'draft', 'Fonte: Terra · Por que: Culpou os "brancos de olhos azuis" ao lado do premiê britânico · Obs.: Defesa do Planalto em https://www.correiobraziliense.com.br/app/noticia/politica/2009/03/27/interna_politica,93246/frase-de-lula-sobre-brancos-de-olhos-azuis-foi-metafora-diz-assessor.shtml'
from people where slug = 'lula'
  and not exists (select 1 from quotes where text = 'É uma crise causada e fomentada por comportamentos irracionais de gente branca de olhos azuis');
insert into quotes (person_id, text, language, said_on, context, source_type, source_url, source_timestamp, difficulty, kind, status, review_note)
select id, 'Nós temos uma Suprema Corte totalmente acovardada', 'pt', '2016-03-04', 'Em telefonema com Dilma Rousseff grampeado pela PF, logo depois da condução coercitiva na Lava Jato. Disse o mesmo do STJ e do Congresso. Quando Moro divulgou o áudio, o decano do STF, Celso de Mello, chamou a fala de "grosseira e injusta".', 'video', 'https://www.correiobraziliense.com.br/app/noticia/politica/2016/03/18/interna_politica,522825/ministros-do-stf-criticam-fala-de-lula-sobre-justica-estar-acovardada.shtml', null, 2, 'polemica', 'draft', 'Fonte: Correio Braziliense · Por que: Grampo chamando o STF de covarde · Obs.: Data da ligação aproximada (4/3/2016); o áudio saiu em 16/3/2016.'
from people where slug = 'lula'
  and not exists (select 1 from quotes where text = 'Nós temos uma Suprema Corte totalmente acovardada');
insert into quotes (person_id, text, language, said_on, context, source_type, source_url, source_timestamp, difficulty, kind, status, review_note)
select id, 'O que o PT fez do ponto de vista eleitoral é o que é feito no Brasil sistematicamente', 'pt', null, 'Em entrevista a uma TV francesa, no auge do escândalo do mensalão. Foi a primeira vez que ele chamou o caso de caixa 2 e a fala foi lida como "todo mundo faz". Meses depois, no Roda Viva, disse que a prática era contra a história do PT.', 'entrevista', 'https://www.terra.com.br/noticias/brasil/eleicoes-2022-o-que-lula-disse-sobre-mensalao-e-petrolao,95528e6fcb33b9bf5ba146a4de0b912evdn9onmx.html', null, 2, 'polemica', 'draft', 'Fonte: Terra · Por que: Minimizou o mensalão dizendo que todo mundo faz · Obs.: Sem data exata; o Terra diz junho de 2005. Ver também https://www.cnnbrasil.com.br/politica/mensalao-completa-20-anos-saiba-como-lula-reagiu-ao-escandalo/'
from people where slug = 'lula'
  and not exists (select 1 from quotes where text = 'O que o PT fez do ponto de vista eleitoral é o que é feito no Brasil sistematicamente');

-- jair-bolsonaro
insert into quotes (person_id, text, language, said_on, context, source_type, source_url, source_timestamp, difficulty, kind, status, review_note)
select id, 'O erro da ditadura foi torturar e não matar', 'pt', null, 'Repetiu a frase em 2008, num protesto no Clube Militar, e em 2016, no programa Pânico, da Jovem Pan. Em outras ocasiões chamou de herói o coronel Brilhante Ustra, condenado por tortura.', 'entrevista', 'https://exame.com/brasil/frases-polemicas-do-candidato-jair-bolsonaro/', null, 1, 'polemica', 'draft', 'Fonte: Exame · Por que: Lamentou que a ditadura não tenha matado mais · Obs.: Datas variam entre as fontes (2008 e junho/julho de 2016); ver https://www.terra.com.br/noticias/brasil/bolsonaro-em-25-frases-polemicas,42807775fee5ce8d514c2e0b803b7969u8szhqse.html'
from people where slug = 'jair-bolsonaro'
  and not exists (select 1 from quotes where text = 'O erro da ditadura foi torturar e não matar');
