select id, 'Pela memória do coronel Carlos Alberto Brilhante Ustra, o pavor de Dilma Rousseff', 'pt', '2016-04-17', 'No voto pelo impeachment de Dilma na Câmara, homenageando o torturador que chefiou o DOI-Codi, onde ela foi presa e torturada. Sofreu representação no Conselho de Ética, arquivada meses depois.', 'discurso', 'https://exame.com/brasil/frases-polemicas-do-candidato-jair-bolsonaro/', null, 1, 'polemica', 'draft', 'Fonte: Exame · Por que: Homenagem a torturador no voto do impeachment'
from people where slug = 'jair-bolsonaro'
  and not exists (select 1 from quotes where text = 'Pela memória do coronel Carlos Alberto Brilhante Ustra, o pavor de Dilma Rousseff');
insert into quotes (person_id, text, language, said_on, context, source_type, source_url, source_timestamp, difficulty, kind, status, review_note)
select id, 'Eu falei que não ia estuprar você porque você não merece', 'pt', '2014-12-09', 'Na tribuna da Câmara, para a deputada Maria do Rosário, repetindo o que tinha dito a ela em 2003. Foi condenado a indenizá-la e a se retratar, decisão mantida pelo STJ, e virou réu no STF por incitação ao estupro.', 'discurso', 'https://exame.com/brasil/frases-polemicas-do-candidato-jair-bolsonaro/', null, 1, 'polemica', 'draft', 'Fonte: Exame · Por que: Condenado por dizer que a deputada "não merecia" ser estuprada · Obs.: A Exame data a frase de 2003; a versão "eu falei" é a repetição de 2014. Condenação em https://exame.com/brasil/stj-mantem-condenacao-de-bolsonaro-por-incitacao-ao-estupro/amp'
from people where slug = 'jair-bolsonaro'
  and not exists (select 1 from quotes where text = 'Eu falei que não ia estuprar você porque você não merece');
