insert into quotes (person_id, text, language, said_on, context, source_type, source_url, source_timestamp, difficulty, kind, status, review_note)
select id, 'Ô Preta, eu não vou discutir promiscuidade com quem quer que seja.', 'pt', '2011-03-28', 'No CQC, quando a cantora Preta Gil perguntou o que ele faria se um filho se apaixonasse por uma mulher negra. Respondeu que seus filhos foram "muito bem educados". Foi acusado de racismo e virou alvo de representação na Câmara.', 'video', 'https://exame.com/brasil/frases-polemicas-do-candidato-jair-bolsonaro/', null, 1, 'polemica', 'draft', 'Fonte: Exame · Por que: Chamou de "promiscuidade" um filho namorar mulher negra · Obs.: Data aproximada (exibição do CQC em março de 2011); o contexto vem de cobertura conhecida do caso, confira na matéria.'
from people where slug = 'jair-bolsonaro'
  and not exists (select 1 from quotes where text = 'Ô Preta, eu não vou discutir promiscuidade com quem quer que seja.');

